const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < n - 1; i++) {
  const a = tok[1 + 2 * i], b = tok[2 + 2 * i];
  adj[a].push(b);
  adj[b].push(a);
}
const par = new Array(n + 1).fill(0);
par[1] = -1;
const order = [1];
for (let i = 0; i < order.length; i++) {
  const v = order[i];
  for (const to of adj[v]) if (to !== par[v]) { par[to] = v; order.push(to); }
}
const sz = new Array(n + 1).fill(1), down = new Array(n + 1).fill(0);
for (let i = order.length - 1; i >= 0; i--) {
  const v = order[i], p = par[v];
  if (p > 0) { sz[p] += sz[v]; down[p] += down[v] + sz[v]; }
}
const ans = new Array(n + 1).fill(0);
ans[1] = down[1];
for (let i = 1; i < order.length; i++) {
  const v = order[i];
  ans[v] = ans[par[v]] - sz[v] + (n - sz[v]);
}
console.log(ans.slice(1).join(" "));

