import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        List<Integer>[] adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            in.nextToken();
            int a = (int) in.nval;
            in.nextToken();
            int b = (int) in.nval;
            adj[a].add(b);
            adj[b].add(a);
        }
        int[] par = new int[n + 1];
        int[] order = new int[n];
        int head = 0, tail = 0;
        par[1] = -1;
        order[tail++] = 1;
        while (head < tail) {
            int v = order[head++];
            for (int to : adj[v]) if (to != par[v]) { par[to] = v; order[tail++] = to; }
        }
        long[] sz = new long[n + 1], down = new long[n + 1], ans = new long[n + 1];
        Arrays.fill(sz, 1);
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i], p = par[v];
            if (p > 0) { sz[p] += sz[v]; down[p] += down[v] + sz[v]; }
        }
        ans[1] = down[1];
        for (int i = 1; i < n; i++) {
            int v = order[i];
            ans[v] = ans[par[v]] - sz[v] + (n - sz[v]);
        }
        StringBuilder out = new StringBuilder();
        for (int v = 1; v <= n; v++) out.append(ans[v]).append(v < n ? " " : "\n");
        System.out.print(out);
    }
}

