#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> par(n + 1, 0), order;
    par[1] = -1;
    order.push_back(1);
    for (size_t i = 0; i < order.size(); i++) {
        int v = order[i];
        for (int to : adj[v]) if (to != par[v]) { par[to] = v; order.push_back(to); }
    }
    vector<ll> sz(n + 1, 1), down(n + 1, 0), ans(n + 1, 0);
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i], p = par[v];
        if (p > 0) { sz[p] += sz[v]; down[p] += down[v] + sz[v]; }
    }
    ans[1] = down[1];
    for (int i = 1; i < n; i++) {
        int v = order[i];
        ans[v] = ans[par[v]] - sz[v] + (n - sz[v]);
    }
    for (int v = 1; v <= n; v++) printf("%lld%c", ans[v], v < n ? ' ' : '\n');
    return 0;
}
